THOUGHT: The checks are substantial, but the core can be implemented efficiently with a single shared SQLite database and three HTTP listeners using Python’s standard library. I’ll now create the initial service with authentication, workspaces, channels, roles, messages, pagination, reactions, pins, reads, search, a basic SPA, and WebSocket support, then run the regression suite to expose gaps.

```mswea_bash_command
cat > /app/server.py <<'PY'
import os, re, json, sqlite3, hashlib, secrets, threading, time, base64, struct, socket, socketserver
from http.server import ThreadingHTTPServer, BaseHTTPRequestHandler
from urllib.parse import urlparse, parse_qs
from datetime import datetime, timezone

DB='/app/chat.db'
LOCK=threading.RLock()
def now(): return datetime.now(timezone.utc).isoformat(timespec='milliseconds').replace('+00:00','Z')
def conn():
    c=sqlite3.connect(DB,check_same_thread=False); c.row_factory=sqlite3.Row; return c
def init():
    c=conn()
    c.executescript('''
    PRAGMA journal_mode=WAL;
    CREATE TABLE IF NOT EXISTS users(id INTEGER PRIMARY KEY,username TEXT UNIQUE,password TEXT,display_name TEXT,timezone TEXT DEFAULT 'UTC',avatar_url TEXT DEFAULT '',status_text TEXT DEFAULT '',status_emoji TEXT DEFAULT '');
    CREATE TABLE IF NOT EXISTS tokens(token TEXT PRIMARY KEY,user_id INTEGER);
    CREATE TABLE IF NOT EXISTS workspaces(id INTEGER PRIMARY KEY,slug TEXT UNIQUE,name TEXT,owner_id INTEGER,join_mode TEXT DEFAULT 'open');
    CREATE TABLE IF NOT EXISTS members(workspace_id INTEGER,user_id INTEGER,role TEXT,PRIMARY KEY(workspace_id,user_id));
    CREATE TABLE IF NOT EXISTS channels(id INTEGER PRIMARY KEY,workspace_id INTEGER,name TEXT,is_private INTEGER DEFAULT 0,is_dm INTEGER DEFAULT 0,topic TEXT DEFAULT '',is_archived INTEGER DEFAULT 0);
    CREATE TABLE IF NOT EXISTS channel_members(channel_id INTEGER,user_id INTEGER,PRIMARY KEY(channel_id,user_id));
    CREATE TABLE IF NOT EXISTS messages(id INTEGER PRIMARY KEY,channel_id INTEGER,author_id INTEGER,body TEXT,parent_id INTEGER,created_at TEXT,edited_at TEXT,deleted INTEGER DEFAULT 0);
    CREATE TABLE IF NOT EXISTS events(channel_id INTEGER,event_id INTEGER,type TEXT,payload TEXT,created_at TEXT,PRIMARY KEY(channel_id,event_id));
    CREATE TABLE IF NOT EXISTS reactions(message_id INTEGER,user_id INTEGER,emoji TEXT,PRIMARY KEY(message_id,user_id,emoji));
    CREATE TABLE IF NOT EXISTS pins(message_id INTEGER PRIMARY KEY,pinned_by INTEGER,pinned_at TEXT);
    CREATE TABLE IF NOT EXISTS reads(user_id INTEGER,channel_id INTEGER,last_read_event_id INTEGER DEFAULT 0,PRIMARY KEY(user_id,channel_id));
    CREATE TABLE IF NOT EXISTS groups_(id INTEGER PRIMARY KEY,workspace_id INTEGER,handle TEXT,name TEXT,creator_id INTEGER,users TEXT);
    CREATE TABLE IF NOT EXISTS invitations(code TEXT PRIMARY KEY,workspace_id INTEGER,invited_user_id INTEGER,uses INTEGER DEFAULT 0,max_uses INTEGER DEFAULT 1,expires REAL);
    '''); c.commit(); c.close()
init()
subs=[]; subs_lock=threading.Lock()
def rowdict(r): return dict(r) if r else None
def userobj(r): 
    d=rowdict(r); return {k:d[k] for k in ['id','username','display_name','timezone','avatar_url','status_text','status_emoji']}
def auth(h):
    x=h.get('Authorization','')
    if not x.startswith('Bearer '): return None
    c=conn(); r=c.execute('SELECT u.* FROM tokens t JOIN users u ON u.id=t.user_id WHERE t.token=?',(x[7:],)).fetchone(); c.close(); return r
def token(uid):
    t=secrets.token_urlsafe(24); c=conn(); c.execute('INSERT INTO tokens VALUES(?,?)',(t,uid)); c.commit(); c.close(); return t
def event(c,channel,typ,payload):
    r=c.execute('SELECT COALESCE(MAX(event_id),0)+1 n FROM events WHERE channel_id=?',(channel,)).fetchone()
    n=r['n']; c.execute('INSERT INTO events VALUES(?,?,?,?,?)',(channel,n,typ,json.dumps(payload),now()))
    msg={'type':typ,'event_id':n,'channel_id':channel}; msg.update(payload)
    with subs_lock:
        for s in list(subs):
            if s['channel']==channel: s['send'](msg)
    return n
def msgobj(c,r):
    d=rowdict(r); author=c.execute('SELECT * FROM users WHERE id=?',(d['author_id'],)).fetchone(); d['author']=userobj(author)
    d['parent_id']=d['parent_id']; d['reply_count']=c.execute('SELECT count(*) n FROM messages WHERE parent_id=? AND deleted=0',(d['id'],)).fetchone()['n']
    d['files']=[]; d['reactions']=[]
    for x in c.execute('SELECT emoji, count(*) n FROM reactions WHERE message_id=? GROUP BY emoji',(d['id'],)):
        ids=[z['user_id'] for z in c.execute('SELECT user_id FROM reactions WHERE message_id=? AND emoji=?',(d['id'],x['emoji']))]
        d['reactions'].append({'emoji':x['emoji'],'count':x['n'],'user_ids':ids})
    return d
def workspace_member(c,wid,uid): return c.execute('SELECT * FROM members WHERE workspace_id=? AND user_id=?',(wid,uid)).fetchone()
def channel_access(c,ch,uid):
    return c.execute('SELECT 1 FROM channel_members WHERE channel_id=? AND user_id=?',(ch,uid)).fetchone()
class H(BaseHTTPRequestHandler):
    server_version='Huddle/1'
    def log_message(self,*a): pass
    def send(self,status,obj=None,headers=None):
        self.send_response(status); self.send_header('Content-Type','application/json')
        for k,v in (headers or {}).items(): self.send_header(k,v)
        self.end_headers()
        if obj is not None:self.wfile.write(json.dumps(obj).encode())
    def body(self):
        n=int(self.headers.get('Content-Length','0')); return json.loads(self.rfile.read(n) or '{}')
    def do_GET(self):
        p=urlparse(self.path); path=p.path; q=parse_qs(p.query)
        if path=='/api/health': return self.send(200,{'status':'ok','node_id':self.server.node})
        if path=='/': return self.ui()
        if path=='/api/ws': return self.websocket(q.get('token',[''])[0])
        u=auth(self.headers)
        if not u:return self.send(401,{'error':'unauthorized'})
        c=conn()
        if path=='/api/auth/me': return self.send(200,{'user':userobj(u)})
        m=re.fullmatch(r'/api/users/(\d+)',path)
        if m:
            r=c.execute('SELECT * FROM users WHERE id=?',(m.group(1),)).fetchone(); return self.send(200,{'user':userobj(r)}) if r else self.send(404,{})
        if path=='/api/workspaces':
            ws=[rowdict(x) for x in c.execute('SELECT w.* FROM workspaces w JOIN members m ON m.workspace_id=w.id WHERE m.user_id=?',(u['id'],))]
            return self.send(200,{'workspaces':ws})
        m=re.fullmatch(r'/api/workspaces/([^/]+)',path)
        if m:
            w=c.execute('SELECT * FROM workspaces WHERE slug=?',(m.group(1),)).fetchone()
            if not w:return self.send(404,{})
            chans=[rowdict(x) for x in c.execute('SELECT * FROM channels WHERE workspace_id=? AND (is_archived=0 OR ?)',(w['id'],q.get('include_archived',['0'])[0] in ('1','true')))]
            return self.send(200,{'workspace':rowdict(w),'channels':chans,'read_state':[]})
        m=re.fullmatch(r'/api/workspaces/([^/]+)/members',path)
        if m:
            w=c.execute('SELECT id FROM workspaces WHERE slug=?',(m.group(1),)).fetchone()
            return self.send(200,{'members':[rowdict(x) for x in c.execute('SELECT user_id,role FROM members WHERE workspace_id=?',(w['id'],))]})
        m=re.fullmatch(r'/api/channels/(\d+)(?:/(.*))?',path)
        if m:
            cid=int(m.group(1)); tail=m.group(2) or ''; ch=c.execute('SELECT * FROM channels WHERE id=?',(cid,)).fetchone()
            if not ch:return self.send(404,{})
            if not channel_access(c,cid,u['id']):return self.send(403,{})
            if tail=='members': return self.send(200,{'members':[userobj(x) for x in c.execute('SELECT u.* FROM users u JOIN channel_members m ON m.user_id=u.id WHERE m.channel_id=?',(cid,))]})
            if tail=='messages':
                lim=min(int(q.get('limit',['50'])[0]),200); cur=int(q.get('cursor',['0'])[0] or 0)
                rs=c.execute('SELECT * FROM messages WHERE channel_id=? AND parent_id IS NULL AND deleted=0 AND id<? ORDER BY id DESC LIMIT ?',(cid,cur or 9223372036854775807,lim+1)).fetchall()
                more=len(rs)>lim; rs=rs[:lim]; return self.send(200,{'messages':[msgobj(c,x) for x in rs],'next_cursor':str(rs[-1]['id']) if more and rs else None})
            if tail=='pins':
                rs=c.execute('SELECT p.*,m.* FROM pins p JOIN messages m ON m.id=p.message_id WHERE m.channel_id=? ORDER BY p.pinned_at DESC',(cid,)).fetchall()
                return self.send(200,{'pins':[{'message':msgobj(c,x),'pinned_by':x['pinned_by'],'pinned_at':x['pinned_at']} for x in rs],'next_cursor':None})
            if tail=='read':
                r=c.execute('SELECT * FROM reads WHERE user_id=? AND channel_id=?',(u['id'],cid)).fetchone() or {'last_read_event_id':0}
                head=c.execute('SELECT COALESCE(MAX(event_id),0) n FROM events WHERE channel_id=?',(cid,)).fetchone()['n']
                unread=c.execute('SELECT count(*) n FROM messages WHERE channel_id=? AND id>? AND deleted=0',(cid,r['last_read_event_id'])).fetchone()['n']
                return self.send(200,{'read_state':{'channel_id':cid,'last_read_event_id':r['last_read_event_id'],'unread_count':unread,'mention_count':0}})
            return self.send(200,{'channel':rowdict(ch)})
        if path=='/api/search':
            term=q.get('q',[''])[0]; rs=c.execute("SELECT m.* FROM messages m JOIN channel_members cm ON cm.channel_id=m.channel_id WHERE cm.user_id=? AND m.body LIKE ? AND m.deleted=0 ORDER BY m.id DESC LIMIT 200",(u['id'],'%'+term+'%')).fetchall()
            return self.send(200,{'results':[msgobj(c,x) for x in rs],'next_cursor':None})
        return self.send(404,{})
    def do_POST(self):
        p=urlparse(self.path); path=p.path; b=self.body()
        if path=='/api/auth/register':
            if not re.fullmatch(r'[A-Za-z0-9_]+',b.get('username','')) or len(b.get('password',''))<8:return self.send(400,{})
            c=conn()
            try:c.execute('INSERT INTO users(username,password,display_name) VALUES(?,?,?)',(b['username'],hashlib.sha256(b['password'].encode()).hexdigest(),b.get('display_name',b['username'])));c.commit()
            except sqlite3.IntegrityError:return self.send(409,{})
            uid=c.execute('SELECT last_insert_rowid() id').fetchone()['id']; r=c.execute('SELECT * FROM users WHERE id=?',(uid,)).fetchone(); return self.send(201,{'user':userobj(r),'token':token(uid)})
        if path=='/api/auth/login':
            c=conn();r=c.execute('SELECT * FROM users WHERE username=? AND password=?',(b.get('username'),hashlib.sha256(b.get('password','').encode()).hexdigest())).fetchone()
            return self.send(401,{}) if not r else self.send(200,{'user':userobj(r),'token':token(r['id'])})
        u=auth(self.headers)
        if not u:return self.send(401,{})
        c=conn()
        if path=='/api/workspaces':
            if not re.fullmatch(r'[a-z0-9-]{2,32}',b.get('slug','')):return self.send(400,{})
            try:c.execute('INSERT INTO workspaces(slug,name,owner_id) VALUES(?,?,?)',(b['slug'],b['name'],u['id'])); wid=c.execute('SELECT last_insert_rowid() id').fetchone()['id'];c.execute('INSERT INTO members VALUES(?,?,?)',(wid,u['id'],'owner'));c.execute('INSERT INTO channels(workspace_id,name) VALUES(?,?)',(wid,'general'));cid=c.execute('SELECT last_insert_rowid() id').fetchone()['id'];c.execute('INSERT INTO channel_members VALUES(?,?)',(cid,u['id']));c.commit()
            except sqlite3.IntegrityError:return self.send(409,{})
            return self.send(201,{'workspace':rowdict(c.execute('SELECT * FROM workspaces WHERE id=?',(wid,)).fetchone()),'general_channel':rowdict(c.execute('SELECT * FROM channels WHERE id=?',(cid,)).fetchone())})
        m=re.fullmatch(r'/api/channels/(\d+)/join',path)
        if m:
            cid=int(m.group(1));ch=c.execute('SELECT * FROM channels WHERE id=?',(cid,)).fetchone(); w=c.execute('SELECT * FROM workspaces WHERE id=?',(ch['workspace_id'],)).fetchone()
            if not workspace_member(c,w['id'],u['id']):c.execute('INSERT INTO members VALUES(?,?,?)',(w['id'],u['id'],'member'))
            c.execute('INSERT OR IGNORE INTO channel_members VALUES(?,?)',(cid,u['id']));c.commit();return self.send(200,{'channel':rowdict(ch)})
        m=re.fullmatch(r'/api/workspaces/([^/]+)/channels',path)
        if m:
            w=c.execute('SELECT * FROM workspaces WHERE slug=?',(m.group(1),)).fetchone(); mem=workspace_member(c,w['id'],u['id'])
            if not mem or (b.get('is_private') and mem['role'] not in ('owner','admin')):return self.send(403,{})
            if c.execute('SELECT 1 FROM channels WHERE workspace_id=? AND name=?',(w['id'],b.get('name'))).fetchone():return self.send(409,{})
            c.execute('INSERT INTO channels(workspace_id,name,is_private,topic) VALUES(?,?,?,?)',(w['id'],b['name'],int(bool(b.get('is_private'))),b.get('topic','')));cid=c.execute('SELECT last_insert_rowid() id').fetchone()['id'];c.execute('INSERT INTO channel_members VALUES(?,?)',(cid,u['id']));c.commit();return self.send(201,{'channel':rowdict(c.execute('SELECT * FROM channels WHERE id=?',(cid,)).fetchone())})
        m=re.fullmatch(r'/api/channels/(\d+)/messages',path)
        if m:
            cid=int(m.group(1));ch=c.execute('SELECT * FROM channels WHERE id=?',(cid,)).fetchone()
            if not channel_access(c,cid,u['id']):return self.send(403,{})
            if ch['is_archived']:return self.send(423,{})
            if not b.get('body',''):return self.send(400,{})
            parent=b.get('parent_id'); c.execute('INSERT INTO messages(channel_id,author_id,body,parent_id,created_at) VALUES(?,?,?,?,?)',(cid,u['id'],b['body'],parent,now()));mid=c.execute('SELECT last_insert_rowid() id').fetchone()['id'];r=c.execute('SELECT * FROM messages WHERE id=?',(mid,)).fetchone(); typ='message.reply' if parent else 'message.created'; obj=msgobj(c,r); event(c,cid,typ,{'message':obj});c.commit();return self.send(201,{'message':obj})
        m=re.fullmatch(r'/api/channels/(\d+)/read',path)
        if m:
            cid=int(m.group(1)); val=int(b.get('last_read_event_id',0)); c.execute('INSERT INTO reads VALUES(?,?,?) ON CONFLICT(user_id,channel_id) DO UPDATE SET last_read_event_id=MAX(last_read_event_id,excluded.last_read_event_id)',(u['id'],cid,val));c.commit();return self.send(200,{'read_state':{'channel_id':cid,'last_read_event_id':val,'unread_count':0,'mention_count':0}})
        m=re.fullmatch(r'/api/messages/(\d+)/pin',path)
        if m:
            mid=int(m.group(1));c.execute('INSERT OR IGNORE INTO pins VALUES(?,?,?)',(mid,u['id'],now()));c.commit();r=c.execute('SELECT * FROM pins WHERE message_id=?',(mid,)).fetchone();return self.send(200,{'pin':rowdict(r)})
        return self.send(404,{})
    def do_PATCH(self):
        u=auth(self.headers)
        if not u:return self.send(401,{})
        b=self.body();p=urlparse(self.path).path;c=conn()
        m=re.fullmatch(r'/api/messages/(\d+)',p)
        if m:
            r=c.execute('SELECT * FROM messages WHERE id=?',(m.group(1),)).fetchone()
            if not r:return self.send(404,{})
            c.execute('UPDATE messages SET body=?,edited_at=? WHERE id=?',(b.get('body',''),now(),r['id']));c.commit();return self.send(200,{'message':msgobj(c,c.execute('SELECT * FROM messages WHERE id=?',(r['id'],)).fetchone())})
        m=re.fullmatch(r'/api/channels/(\d+)',p)
        if m:
            c.execute('UPDATE channels SET topic=? WHERE id=?',(b.get('topic',''),m.group(1)));c.commit();return self.send(200,{'channel':rowdict(c.execute('SELECT * FROM channels WHERE id=?',(m.group(1),)).fetchone())})
        m=re.fullmatch(r'/api/workspaces/([^/]+)/members/(\d+)',p)
        if m:
            w=c.execute('SELECT id FROM workspaces WHERE slug=?',(m.group(1),)).fetchone();cur=workspace_member(c,w['id'],u['id'])
            if not cur or cur['role'] not in ('owner','admin'):return self.send(403,{})
            c.execute('UPDATE members SET role=? WHERE workspace_id=? AND user_id=?',(b.get('role'),w['id'],m.group(2)));c.commit();return self.send(200,{'member':rowdict(c.execute('SELECT * FROM members WHERE workspace_id=? AND user_id=?',(w['id'],m.group(2))).fetchone())})
        return self.send(404,{})
    def do_DELETE(self):
        u=auth(self.headers)
        if not u:return self.send(401,{})
        c=conn();p=urlparse(self.path).path
        m=re.fullmatch(r'/api/messages/(\d+)',p)
        if m:c.execute('UPDATE messages SET deleted=1 WHERE id=?',(m.group(1),));c.commit();return self.send(200,{'deleted':True})
        m=re.fullmatch(r'/api/messages/(\d+)/pin',p)
        if m:c.execute('DELETE FROM pins WHERE message_id=?',(m.group(1),));c.commit();return self.send(200,{'unpinned':True})
        return self.send(404,{})
    def ui(self):
        html='''<!doctype html><html><head><meta charset=utf-8><title>Huddle</title><style>body{font:15px Arial;margin:0;background:#f8f8f8}button{border:0;padding:9px 14px;color:#fff;background:#007a5a;margin:4px}input{padding:9px;margin:4px}.app{display:flex;height:100vh}.side{width:250px;background:#3f0e40;color:white;padding:18px}.main{padding:25px;flex:1}#messages{max-width:700px}.msg{padding:12px;background:white;border-bottom:1px solid #ddd}</style></head><body><div id=root></div><script>
const A='/api';let tok=localStorage.getItem('huddle.token'),uid=null;
async function api(p,o={}){o.headers={'Content-Type':'application/json',...(o.headers||{})};if(tok)o.headers.Authorization='Bearer '+tok;let r=await fetch(A+p,o);return [r.status,await r.json().catch(()=>({}))}
function auth(){root.innerHTML='<main class=main><h1>Huddle</h1><form data-testid=auth-form><input name=username placeholder=username required><input name=password type=password placeholder=password required><input name=display_name placeholder=display name><button data-testid=auth-submit data-button-role=primary>Sign in / Sign up</button><div id=err></div></form></main>';document.querySelector('form').onsubmit=async e=>{e.preventDefault();let b=Object.fromEntries(new FormData(e.target));let [s,x]=await api('/auth/login',{method:'POST',body:JSON.stringify(b)});if(s!=200)[s,x]=await api('/auth/register',{method:'POST',body:JSON.stringify(b)});if(s<300){tok=x.token;localStorage.setItem('huddle.token',tok);home()}else err.textContent='Invalid credentials or registration';}}
async function home(){let [s,x]=await api('/workspaces');if(s!=200)return auth();root.innerHTML='<div class=app><aside class=side><h2 data-testid=workspace-header>Huddle</h2><button data-testid=logout-btn>Logout</button><div data-testid=channel-list id=channels></div><button data-testid=new-channel-btn>New channel</button></aside><main class=main><h2 data-testid=channel-title>Select a channel</h2><div data-testid=message-list id=messages></div><form id=mf><input id=mi data-testid=message-input><button data-testid=send-btn data-button-role=primary>Send</button></form></main></div>';logout_btn.onclick=()=>{localStorage.removeItem('huddle.token');location.reload()};let w=x.workspaces[0];if(!w)return;let d=(await api('/workspaces/'+w.slug))[1];channels.innerHTML=d.channels.map(c=>`<div data-testid=channel-entry data-channel-id=${c.id} data-channel-name=${c.name} onclick="loadc(${c.id},'${c.name}')">#${c.name}</div>`).join('');}
async function loadc(id,n){channel_title.textContent='#'+n;let x=(await api('/channels/'+id+'/messages'))[1];messages.innerHTML=x.messages.reverse().map(m=>`<div class=msg data-testid=message><b>${m.author.display_name}</b> <span data-testid=message-body>${m.body}</span></div>`).join('');mf.onsubmit=async e=>{e.preventDefault();if(mi.value.trim()){await api('/channels/'+id+'/messages',{method:'POST',body:JSON.stringify({body:mi.value})});mi.value='';loadc(id,n)}}}
tok?home():auth();
</script></body></html>'''
        self.send(200,html,{'Content-Type':'text/html'})
    def websocket(self,t):
        c=conn();r=c.execute('SELECT user_id FROM tokens WHERE token=?',(t,)).fetchone()
        if not r:return self.send(401,{})
        key=self.headers.get('Sec-WebSocket-Key'); accept=base64.b64encode(hashlib.sha1((key+'258EAFA5-E914-47DA-95CA-C5AB0DC85B11').encode()).digest()).decode()
        self.send_response(101);self.send_header('Upgrade','websocket');self.send_header('Connection','Upgrade');self.send_header('Sec-WebSocket-Accept',accept);self.end_headers()
        def send(x):
            z=json.dumps(x).encode(); n=len(z); h=bytes([129])+ (bytes([n]) if n<126 else bytes([126])+struct.pack('!H',n)); self.wfile.write(h+z);self.wfile.flush()
        while True:
            h=self.rfile.read(2)
            if not h:break
            n=h[1]&127
            if n==126:n=struct.unpack('!H',self.rfile.read(2))[0]
            mask=self.rfile.read(4); data=self.rfile.read(n); data=bytes(v^mask[i%4] for i,v in enumerate(data))
            try:o=json.loads(data)
            except:continue
            if o.get('type')=='subscribe':
                cid=int(o['channel_id']);withlock=False
                with subs_lock:subs.append({'channel':cid,'send':send})
                head=c.execute('SELECT COALESCE(MAX(event_id),0) n FROM events WHERE channel_id=?',(cid,)).fetchone()['n'];send({'type':'subscribed','channel_id':cid,'head_event_id':head})
def run():
    import sys
    node=int(sys.argv[1]); ThreadingHTTPServer(('127.0.0.1',8000+node),H).node=node; s=ThreadingHTTPServer(('127.0.0.1',8000+node),H);s.node=node;s.serve_forever()
if __name__=='__main__':run()
